// @vitest-environment node
import { readFileSync } from 'node:fs'
import { geometryPrecheck, PRECHECK_REASONS, type PrecheckReason } from './geometryPrecheck'

// Vectors generated by the Python geometry module (synthetic shapes, not NASA data).
type Vector = {
  name: string
  geometry?: unknown
  circle?: unknown
  expected: { valid: boolean; reason: string | null; vertex_count: number | null }
}
const file = JSON.parse(
  readFileSync(new URL('../../../tests/data/selection_vectors.json', import.meta.url), 'utf8'),
) as { client_precheck_reasons: string[]; vectors: Vector[] }

const polygonVectors = file.vectors.filter((v) => v.geometry !== undefined)

function square(west: number, south: number, size: number): number[][] {
  return [
    [west, south],
    [west + size, south],
    [west + size, south + size],
    [west, south + size],
    [west, south],
  ]
}

describe('geometryPrecheck against the Python vectors', () => {
  it('lists the same client reasons as the vector file', () => {
    expect([...PRECHECK_REASONS].sort()).toEqual([...file.client_precheck_reasons].sort())
  })

  it.each(polygonVectors.map((v) => [v.name, v] as const))('%s', (_name, vector) => {
    const result = geometryPrecheck(vector.geometry)
    const reason = vector.expected.reason
    if (reason !== null && file.client_precheck_reasons.includes(reason)) {
      // A reason the client must catch: same reason, and the submitted vertex count.
      expect(result).toMatchObject({ ok: false, reason })
      if (!result.ok) expect(result.vertexCount).toBe(vector.expected.vertex_count)
    } else {
      // Valid, or a reason only the server decides (malformed, outside the extent).
      expect(result.ok).toBe(true)
    }
  })
})

describe('geometryPrecheck', () => {
  it('accepts a polygon with a hole and a multipolygon with a part inside a hole', () => {
    const outer = square(-121, 36, 4)
    const hole = square(-120, 37, 2)
    const island = square(-119.5, 37.5, 1)
    expect(geometryPrecheck({ type: 'Polygon', coordinates: [outer, hole] }).ok).toBe(true)
    expect(
      geometryPrecheck({ type: 'MultiPolygon', coordinates: [[outer, hole], [island]] }).ok,
    ).toBe(true)
  })

  it('accepts a hole that touches the shell at one vertex', () => {
    const outer = square(-121, 36, 4)
    const hole = [
      [-121, 38],
      [-120, 37],
      [-120, 39],
      [-121, 38],
    ]
    expect(geometryPrecheck({ type: 'Polygon', coordinates: [outer, hole] }).ok).toBe(true)
  })

  it('rejects a part inside another part, and a hole outside the shell', () => {
    const big = square(-121, 36, 4)
    const small = square(-120, 37, 1)
    expect(geometryPrecheck({ type: 'MultiPolygon', coordinates: [[big], [small]] })).toMatchObject(
      {
        ok: false,
        reason: 'self_intersection',
      },
    )
    expect(
      geometryPrecheck({ type: 'Polygon', coordinates: [small, square(-110, 37, 1)] }),
    ).toMatchObject({ ok: false, reason: 'self_intersection' })
  })

  it('rejects an outline that doubles back along an edge', () => {
    const spike = [
      [-120, 36],
      [-118, 36],
      [-119, 36],
      [-119, 38],
      [-120, 36],
    ]
    expect(geometryPrecheck({ type: 'Polygon', coordinates: [spike] })).toMatchObject({
      ok: false,
      reason: 'self_intersection',
    })
  })

  it('checks too many vertices before coordinate range', () => {
    const ring = Array.from({ length: 1001 }, () => [500, 500])
    expect(geometryPrecheck({ type: 'Polygon', coordinates: [ring] })).toEqual({
      ok: false,
      reason: 'too_many_vertices',
      vertexCount: 1001,
    })
  })

  it('reports an out-of-range value before too few vertices, and a non-finite one as out of range', () => {
    expect(
      geometryPrecheck({
        type: 'Polygon',
        coordinates: [
          [
            [200, 0],
            [200, 0],
            [200, 0],
            [200, 0],
          ],
        ],
      }),
    ).toMatchObject({ ok: false, reason: 'coordinate_out_of_range' })
    expect(
      geometryPrecheck({
        type: 'Polygon',
        coordinates: [
          [
            [Number.NaN, 0],
            [1, 0],
            [1, 1],
            [Number.NaN, 0],
          ],
        ],
      }),
    ).toMatchObject({ ok: false, reason: 'coordinate_out_of_range' })
  })

  it('leaves malformed input to the server', () => {
    for (const bad of [
      null,
      5,
      'x',
      {},
      { type: 'Polygon' },
      { type: 'Polygon', coordinates: [] },
    ]) {
      expect(geometryPrecheck(bad)).toEqual({ ok: true, vertexCount: null })
    }
    expect(
      geometryPrecheck({
        type: 'Polygon',
        coordinates: [
          [
            [1, 'a'],
            [2, 3],
            [3, 4],
            [1, 'a'],
          ],
        ],
      }).ok,
    ).toBe(true)
  })

  it('never reports a reason outside PRECHECK_REASONS', () => {
    const reasons = new Set<PrecheckReason>()
    for (const v of polygonVectors) {
      const r = geometryPrecheck(v.geometry)
      if (!r.ok) reasons.add(r.reason)
    }
    for (const reason of reasons) expect(PRECHECK_REASONS).toContain(reason)
  })
})
